function shellSplit(s){const result=[];let word='',quote=null,started=false;for(let i=0;i<s.length;i++){const c=s[i];if(quote){if(c===quote)quote=null;else if(c==='\\'&&quote==='"'&&['"','\\','$','`'].includes(s[i+1]))word+=s[++i];else word+=c;}else if(c==='"'||c==="'"){quote=c;started=true;}else if(c==='\\'){if(++i>=s.length)throw new PError('ValueError','Trailing escape');word+=s[i];started=true;}else if(/\s/.test(c)){if(started){result.push(word);word='';started=false;}}else{word+=c;started=true;}}if(quote)throw new PError('ValueError','No closing quotation');if(started)result.push(word);return result;}
module('shlex',{split:native(a=>shellSplit(a[0])),quote:native(a=>/^[\w@%+=:,./-]+$/.test(a[0])?a[0]:"'"+a[0].replace(/'/g,"'\"'\"'")+"'")});
const regex=p=>new RegExp(p.replace(/\(\?i\)/g,''),p.includes('(?i)')?'iu':'u');
module('re',{escape:native(a=>a[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&')),compile:native(a=>({search:native(b=>regex(a[0]).exec(b[0]))})),fullmatch:native(a=>{const m=regex('^(?:'+a[0]+')$').exec(a[1]);return m;}),sub:native(a=>a[2].replace(new RegExp(a[0],'gu'),(...parts)=>typeof a[1]==='string'?a[1]:$call(a[1],[parts.slice(0,-2)])))});
export function serialize(root){const nodes=[],seen=new Map();function enc(v){if(v===null||typeof v!=='object')return v;if(seen.has(v))return {$ref:seen.get(v)};const id=nodes.length;seen.set(v,id);nodes.push(null);let node;if(v instanceof PObject)node={type:'object',cls:v.cls.name,attrs:enc(v.attrs)};else if(v instanceof PythonRandom)node={type:'random',state:v.getstate()};else if(v instanceof PD)node={type:v instanceof PCounter?'counter':'dict',values:[...v.entries()].map(([k,x])=>[enc(k),enc(x)])};else if(v instanceof PS)node={type:'set',frozen:v.frozen,values:[...v].map(enc)};else if(Array.isArray(v))node={type:v.tuple?'tuple':'list',values:v.map(enc)};else throw Error('Unsupported save object');nodes[id]=node;return {$ref:id};}return JSON.stringify({format:'civilization-js',version:1,root:enc(root),nodes});}
export function deserialize(text){const data=JSON.parse(text);if(data.format!=='civilization-js'||data.version!==1||!Array.isArray(data.nodes))throw Error('This is not a supported Civilization save.');const memo=new Map();function dec(v){if(v===null||typeof v!=='object')return v;const id=v.$ref;if(memo.has(id))return memo.get(id);const n=data.nodes[id];if(!n)throw Error('Invalid save reference');let o;if(n.type==='object'){const cls=$get($import('civsim'),n.cls);if(!cls?.isclass)throw Error('Invalid save class');o=new PObject(cls);}else if(n.type==='random')o=new PythonRandom(0);else if(n.type==='dict')o=new PD();else if(n.type==='counter')o=new PCounter();else if(n.type==='set')o=new PS([],n.frozen);else if(n.type==='tuple')o=$tuple([]);else if(n.type==='list')o=[];else throw Error('Invalid save type');memo.set(id,o);if(n.type==='object')o.attrs=dec(n.attrs);else if(n.type==='random')o.setstate(n.state);else if(o instanceof PD)for(const [k,x] of n.values)o.set(dec(k),dec(x));else if(o instanceof PS)for(const x of n.values)o.add(dec(x));else if(Array.isArray(o))o.push(...n.values.map(dec));return o;}return dec(data.root);}
